// ─── Spam scoring + field normalisation ───
// Reads the form data, scores it 0–10, attaches metadata for later branches.
const raw = $input.first().json;
const body = raw.body || raw;

const msg   = String(body.message || '').toLowerCase();
const name  = String(body.name    || '').toLowerCase();
const email = String(body.email   || '').toLowerCase();

let score = 0;
const reasons = [];

// Honeypot (should never be filled by humans — form strips it client-side)
if (body.company_url) { score += 10; reasons.push('honeypot-filled'); }

// Spam keywords
const SPAM_WORDS = [
  'viagra', 'casino', 'crypto', 'bitcoin', 'investment opportunity',
  'seo services', 'rank #1', 'click here', 'free money', 'lottery',
  'inheritance', 'urgent reply', 'congratulations you have won',
  'cheap loan', 'work from home', 'make money fast'
];
for (const w of SPAM_WORDS) {
  if (msg.includes(w)) { score += 3; reasons.push(`keyword:${w}`); }
}

// Excessive URLs
const urlCount = (msg.match(/https?:\/\//g) || []).length;
if (urlCount > 1) { score += urlCount * 2; reasons.push(`urls:${urlCount}`); }
if (urlCount > 5) { score += 10; reasons.push('too-many-urls'); }

// Disposable email domains
const BAD_DOMAINS = ['mailinator.com', 'tempmail', '10minute', 'guerrillamail', 'sharklasers'];
for (const d of BAD_DOMAINS) {
  if (email.includes(d)) { score += 5; reasons.push(`disposable:${d}`); }
}

// Trivially short message
if (msg.trim().length < 10) { score += 3; reasons.push('too-short'); }

// ALL CAPS SHOUTING
const upper = msg.match(/[A-Z]/g) || [];
if (msg.length > 30 && upper.length / msg.length > 0.4) {
  score += 2; reasons.push('all-caps');
}

// Gibberish name (no vowels)
if (name && /^[a-z]+$/.test(name) && !/[aeiou]/.test(name)) {
  score += 2; reasons.push('gibberish-name');
}

return [{
  json: {
    name:    body.name    || '',
    email:   body.email   || '',
    phone:   body.phone   || '',
    brand:   body.brand   || '',
    message: body.message || '',
    source:  body.source  || 'webdesignhub.net',
    submitted_at: body.submitted_at || new Date().toISOString(),
    _spam_score: score,
    _is_spam: score >= 5,
    _reasons: reasons.join(', ') || 'clean'
  }
}];

